mapper.update:
UPDATE `user`
SET custom_total_count = #{totalCount},
    custom_today_count = #{todayCount},
    custom_last_study_date = #{lastStudyDate}
WHERE id = #{userId}

UPDATE `user`
SET total_count = total_count + 1,
    today_count = CASE WHEN last_study_date = #{today} THEN today_count + 1 ELSE 1 END,
    last_study_date = #{today}
WHERE id = #{userId}

UPDATE `user`
SET custom_total_count = custom_total_count + 1,
    custom_today_count = CASE WHEN custom_last_study_date = #{today} THEN custom_today_count + 1 ELSE 1 END,
    custom_last_study_date = #{today}
WHERE id = #{userId}
